body:
DSN-2 (F13) theme API is landed in crates/gui/src/theme.rs. Additive only; dark unchanged. New surface:
  pub struct Palette { background, surface, surface_e0/e2/e3, surface_hover, surface_selected, border, border_strong, text, text_secondary, text_muted, text_disabled, accent, accent_pressed, success, warning, danger, info, dim }
  pub const DARK: Palette;  pub const LIGHT: Palette;
  #[derive(Default)] pub enum ThemeMode { #[default] Dark, Light }
  impl ThemeMode { pub fn palette(self) -> &'static Palette }
  pub fn apply_theme(ctx: &egui::Context, mode: ThemeMode)   // apply(ctx) == apply_theme(ctx, Dark)
All existing pub consts stay, now aliases of DARK.

EXACT app.rs HUNK for the toggle (app.rs is integrator-owned; I did NOT touch it):

(1) struct App, after `pub diagrams: diagrams::DiagramsState,`:
+    /// Active theme (F13); toggled by Ctrl+T or the View menu.
+    pub theme_mode: theme::ThemeMode,

(2) App::new, after `diagrams: Default::default(),`:
+            theme_mode: theme::ThemeMode::Dark,

(3) toolbar(), right after the Export menu block (`});` at end of the `ui.menu_button("Export ▾", ...)`):
+            ui.menu_button("View ▾", |ui| {
+                let light = self.theme_mode == theme::ThemeMode::Light;
+                if ui.selectable_label(light, "Light theme").clicked() {
+                    self.theme_mode = theme::ThemeMode::Light;
+                    theme::apply_theme(ui.ctx(), self.theme_mode);
+                    ui.close();
+                }
+                if ui.selectable_label(!light, "Dark theme").clicked() {
+                    self.theme_mode = theme::ThemeMode::Dark;
+                    theme::apply_theme(ui.ctx(), self.theme_mode);
+                    ui.close();
+                }
+            });

(4) handle_keyboard(): add ctrl_t to the ctx.input tuple
-        let (tab, slash, esc, question, g, enter, j, k, ctrl_s, ctrl_k) = ctx.input(|i| {
+        let (tab, slash, esc, question, g, enter, j, k, ctrl_s, ctrl_k, ctrl_t) = ctx.input(|i| {
             (
                 ...,
                 i.key_pressed(egui::Key::K) && i.modifiers.ctrl,
+                i.key_pressed(egui::Key::T) && i.modifiers.ctrl,
             )
         });
 and after the `if ctrl_k { ... return; }` block:
+        if ctrl_t {
+            self.theme_mode = match self.theme_mode {
+                theme::ThemeMode::Dark => theme::ThemeMode::Light,
+                theme::ThemeMode::Light => theme::ThemeMode::Dark,
+            };
+            theme::apply_theme(ctx, self.theme_mode);
+            return;
+        }

Until this lands the light palette is reachable only from theme tests. No new deps.
